"""AI-content labels: visible text, IPTC digital-source metadata and an export manifest."""

import io
from xml.sax.saxutils import escape

from PIL import Image
from PIL.PngImagePlugin import PngInfo

LABEL = "Made with AI"
SOURCE_TYPE = "http://cv.iptc.org/newscodes/digitalsourcetype/trainedAlgorithmicMedia"
TOOL = "CinemaFabric"


def xmp(title: str = "") -> str:
    """An XMP packet marking the file as generated by a trained model (IPTC DigitalSourceType)."""
    title_xml = f'<dc:title><rdf:Alt><rdf:li xml:lang="x-default">{escape(title)}</rdf:li></rdf:Alt></dc:title>' if title else ""
    return (
        '<?xpacket begin="﻿" id="W5M0MpCehiHzreSzNTczkc9d"?>'
        '<x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">'
        '<rdf:Description rdf:about="" xmlns:Iptc4xmpExt="http://iptc.org/std/Iptc4xmpExt/2008-02-29/" '
        'xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:xmp="http://ns.adobe.com/xap/1.0/">'
        f"<Iptc4xmpExt:DigitalSourceType>{SOURCE_TYPE}</Iptc4xmpExt:DigitalSourceType>"
        f"<xmp:CreatorTool>{TOOL}</xmp:CreatorTool>"
        f'<dc:description><rdf:Alt><rdf:li xml:lang="x-default">{LABEL}</rdf:li></rdf:Alt></dc:description>'
        f"{title_xml}</rdf:Description></rdf:RDF></x:xmpmeta>"
        '<?xpacket end="r"?>'
    )


def png_bytes(img: Image.Image, title: str = "") -> bytes:
    info = PngInfo()
    info.add_itxt("XML:com.adobe.xmp", xmp(title))
    info.add_text("Software", TOOL)
    info.add_text("Description", LABEL)
    buf = io.BytesIO()
    img.save(buf, "PNG", pnginfo=info)
    return buf.getvalue()


def is_labelled(png: bytes) -> bool:
    return SOURCE_TYPE in (Image.open(io.BytesIO(png)).info.get("XML:com.adobe.xmp") or "")


def ffmpeg_tags(title: str) -> list[str]:
    tags = {"title": title, "comment": f"{LABEL} with {TOOL}. IPTC digital source type: {SOURCE_TYPE}",
            "description": LABEL, "encoder_tool": TOOL}
    args: list[str] = []
    for key, value in tags.items():
        args += ["-metadata", f"{key}={value}"]
    return args
